/* W9.5 / W11.6: fictional text-only material workflow, RAM only. No LMS, files or rights writes. */
const LIBRARY_ROUTES=['/staff/library','/portal/drive'];
const LIBRARY={role:'teacher',missingLead:false,selected:null,draft:{kind:'material',title:'',goal:'',body:'',example:'',exercise:'',translation:''},items:[],note:'',checked:false,target:'T-01',error:null,answers:{},practice:{},preview:false};
const LIBRARY_ROLES={teacher:['Lehrkraft · Musterkurs T-01','Teacher · sample course T-01'],lead:['Fachleitung · Musterfach','Subject lead · sample subject'],head:['Schulleitung · Muster','School lead · sample'],other:['Nicht zugeordnete Musterrolle','Unassigned sample role']};
function libraryStaff(){return route()==='/staff/library'}
function libraryItem(){return LIBRARY.items.find(x=>x.id===LIBRARY.selected)}
function libraryVersion(){return libraryItem()?.versions.at(-1)}
function libraryCopy(v){return JSON.parse(JSON.stringify(v))}
function libraryStatus(v){return v.status==='approved'?t('Fassung freigegeben · lokal','Version approved · local'):v.status==='revision'?t('Überarbeitung erforderlich','Revision required'):t('Prüfung ausstehend','Review pending')}
function libraryButton(de,en,act){return `<button type="button" class="btn secondary" data-library-action="${act}">${t(de,en)}</button>`}
function libraryEvent(x,de,en,note=''){x.history.push({de,en,note,at:new Date().toISOString()})}
function libraryFail(de,en){LIBRARY.error=[de,en];render();document.getElementById('library-error')?.focus()}
function libraryContent(d){return `<h3>${esc(d.title)}</h3><p><b>${t('Lernziel','Learning objective')}</b>: ${esc(d.goal)}</p><p class="learning-preserve">${esc(d.body)}</p>${d.kind==='vocabulary'?`<p><b>${t('Deutscher Fachbegriff bleibt führend','German technical term remains primary')}</b></p><p class="learning-preserve">${t('Beispiel','Example')}: ${esc(d.example)}</p><p class="learning-preserve">${t('Übungsauftrag','Practice prompt')}: ${esc(d.exercise)}</p>${d.translation?`<p class="learning-preserve">${t('Ergänzende Erklärung · kein weiteres Portalangebot','Supplementary explanation · no additional portal language')}: ${esc(d.translation)}</p>`:''}`:''}`}
function libraryEditor(){const d=LIBRARY.draft;return `<section class="learning-panel"><h2>${t('Eigener Materialentwurf','Your material draft')}</h2><p>${t('Musterfach Mathematik · Kurs T-01 · Mustersemester. Textprobe statt Datei. Der Entwurf ist nur in dieser Lehrkraftansicht sichtbar.','Sample subject mathematics · course T-01 · sample semester. Text sample instead of a file. This draft is visible only in this teacher view.')}</p><label class="field">${t('Materialart','Material type')}<select id="library-kind"><option value="material" ${d.kind==='material'?'selected':''}>${t('Lehrmaterial','Teaching material')}</option><option value="vocabulary" ${d.kind==='vocabulary'?'selected':''}>${t('Fachwortschatz','Technical vocabulary')}</option></select></label>${[['title',d.kind==='vocabulary'?t('Deutscher Fachbegriff','German technical term'):t('Titel','Title')],['goal',t('Curriculares Lernziel · fiktiv','Curricular objective · fictional')],['body',d.kind==='vocabulary'?t('Definition · fiktiv','Definition · fictional'):t('Materialtext · fiktiv','Material text · fictional')],...(d.kind==='vocabulary'?[['example',t('Beispiel · fiktiv','Example · fictional')],['exercise',t('Übungsbezug · fiktiv','Practice prompt · fictional')],['translation',t('Ergänzende Erklärung · optional','Supplementary explanation · optional')]]:[])].map(([key,label])=>`<label class="field">${label}<textarea id="library-${key}" maxlength="2000">${esc(d[key])}</textarea></label>`).join('')}<label class="attendance-check"><input id="library-missing-lead" type="checkbox" ${LIBRARY.missingLead?'checked':''}>${t('Musterszenario: Keine Fachleitung benannt','Sample scenario: no subject lead assigned')}</label><div class="actions">${libraryButton('Neue Musterfassung zur Prüfung vorlegen','Submit new sample version for review','submit')}${libraryButton('Neuen Entwurf beginnen','Start new draft','new')}</div>${libraryButton('Internen Entwurf ansehen · keine Freigabe','Inspect internal draft · not an approval','preview')}${LIBRARY.preview?`<section class="library-preview"><h3>${t('Interne Textprobe · keine Freigabe','Internal text preview · not approved')}</h3>${libraryContent(d)}</section>`:''}</section>`}
function libraryReview(){const x=libraryItem(),v=libraryVersion();if(!v)return '';const reviewer=v.reviewer==='head'?t('Schulleitung','School lead'):t('Fachleitung','Subject lead');return `<section class="learning-panel"><h2>${x.id} · ${t('Version','Version')} ${v.number}</h2><p class="learning-status">${libraryStatus(v)}</p><p>${t('Autor','Author')}: ${x.author} · ${t('Prüfzuständigkeit dieser Fassung','Reviewer for this version')}: ${reviewer}</p>${libraryContent(v.data)}${v.status==='pending'&&LIBRARY.role===v.reviewer?`<label class="field">${t('Fachliche Prüfnotiz / Überarbeitungsgrund · intern','Subject review note / revision reason · internal')}<textarea id="library-note" maxlength="2000">${esc(LIBRARY.note)}</textarea></label><label class="attendance-check"><input id="library-checked" type="checkbox" ${LIBRARY.checked?'checked':''}>${t('Inhalt, Lernziel und curriculare Passung dieser Fassung geprüft','Content, learning objective and curriculum fit of this version reviewed')}</label><div class="actions">${libraryButton('Fassung lokal freigeben','Approve version locally','approve')}${libraryButton('Zur Überarbeitung zurückgeben','Return for revision','return')}</div>`:''}${LIBRARY.role==='teacher'&&v.status==='approved'?`<label class="field">${t('Unveränderte Fassung wiederverwenden','Reuse unchanged version')}<select id="library-target"><option value="T-01" ${LIBRARY.target==='T-01'?'selected':''}>T-01 · ${t('eigener Musterkurs','own sample course')}</option><option value="T-02" ${LIBRARY.target==='T-02'?'selected':''}>T-02 · ${t('fiktives Folgesemester','fictional next semester')}</option></select></label>${libraryButton('Freigegebene Fassung lokal zuordnen','Assign approved version locally','assign')}`:''}<p>${t('Neue Änderungen bleiben Entwurf; die bisherige Freigabe wird nicht auf neue Texte übertragen.','New changes remain a draft; previous approval does not apply to new text.')}</p><details><summary>${t('Fassungen, Prüfungen und Wiederverwendung','Versions, reviews and reuse')}</summary>${x.versions.map(p=>`<article class="case-message"><h3>${t('Version','Version')} ${p.number} · ${libraryStatus(p)}</h3>${libraryContent(p.data)}<p>${t('Prüfung','Review')}: ${esc(p.reviewNote||t('offen','pending'))}</p><p>${t('Unveränderte Zuordnungen','Unchanged assignments')}: ${p.assignments.map(a=>esc(a.course)).join(', ')||t('keine','none')}</p>${p.status==='approved'&&LIBRARY.role==='teacher'?['T-01','T-02'].map(course=>`<button class="btn secondary" data-library-action="reuse" data-library-version="${p.number}" data-library-course="${course}">${t('Diese Fassung unverändert zuordnen','Assign this unchanged version')} · ${course}</button>`).join(' '):''}</article>`).join('')}<ol>${x.history.map(e=>`<li>${esc(e.at)} · ${t(e.de,e.en)} ${esc(e.note)}</li>`).join('')}</ol></details></section>`}
function libraryParticipant(){const entries=LIBRARY.items.flatMap(x=>x.versions.filter(v=>v.status==='approved'&&v.assignments.some(a=>a.course==='T-01')).map(v=>({x,v})));return `<section class="learning-panel"><h2>${t('Mein zugeordnetes Material · T-01','My assigned material · T-01')}</h2><p>${t('Eine fiktive Person im Musterkurs T-01. Nur ausdrücklich zugeordnete freigegebene Fassungen. Keine Cloud-Dateien oder Downloads.','One fictional person in sample course T-01. Only explicitly assigned approved versions. No cloud files or downloads.')}</p>${entries.length?entries.map(({x,v})=>{const key=x.id+'-'+v.number,p=LIBRARY.practice[key]||[];return `<article class="library-material">${libraryContent(v.data)}<p>${x.id} · ${t('Version','Version')} ${v.number} · ${t('Autor','Author')}: ${x.author}</p>${v.data.kind==='vocabulary'?`<label class="field">${t('Eigene Musterantwort','Your sample answer')}<textarea data-library-answer="${key}" maxlength="2000">${esc(LIBRARY.answers[key]||'')}</textarea></label><button class="btn secondary" data-library-practice="${key}" data-result="repeat">${t('Antwort vormerken · erneut üben','Record answer · practise again')}</button> <button class="btn secondary" data-library-practice="${key}" data-result="reviewed">${t('Antwort vormerken · selbst durchgesehen','Record answer · self-reviewed')}</button><p>${t('Manuelle Selbstreflexion, keine automatische Bewertung, Note oder adaptive Wiederholung. Konkrete Trainerregeln sind noch festzulegen.','Manual self-reflection, no automatic assessment, grade or adaptive repetition. Trainer rules remain to be specified.')}</p><details><summary>${t('Nur mein lokaler Übungsverlauf','Only my local practice history')} (${p.length})</summary>${p.map(a=>`<article class="case-message"><p>${esc(a.at)} · ${a.result==='repeat'?t('Erneut üben','Practise again'):t('Selbst durchgesehen','Self-reviewed')}</p><p class="learning-preserve">${esc(a.answer)}</p></article>`).join('')}</details>`:''}</article>`}).join(''):`<p class="learning-empty">${t('Noch keine freigegebene Fassung deinem Musterkurs zugeordnet.','No approved version assigned to your sample course yet.')}</p>`}</section>`}
function libraryPage(){const staff=libraryStaff(),allowed=!staff||LIBRARY.role!=='other';return `<section class="v2-content learning-journey library-journey"><span class="eyebrow">${t('MATERIALIEN · LOKALE MUSTERBIBLIOTHEK','MATERIALS · LOCAL SAMPLE LIBRARY')}</span><h1 id="library-heading" tabindex="-1">${staff?t('Vom Entwurf zur geprüften Fassung.','From draft to reviewed version.'):t('Dein Material. Deine Übung.','Your materials. Your practice.')}</h1><p class="learning-notice">${t('Nur fiktive Texte im Arbeitsspeicher. Kein Datei-Upload, Versand, echter LMS-Zugriff oder verbindliches Curriculum. Neuladen verwirft alle Muster. Rollenwahl ist keine Anmeldung. OpenOLAT bleibt die vorgesehene operative Lernstrecke.','Fictional text in memory only. No file upload, sending, actual LMS access or binding curriculum. Reloading discards all samples. Role selection is not sign-in. OpenOLAT remains the intended operational learning platform.')}</p><nav class="portal-nav"><a href="#/staff/library">${t('Bibliothek · Musterrollen','Library · sample roles')}</a><a href="#/portal/drive">${t('Eigene Materialien · Demo','My materials · demo')}</a><a href="#/portal/learning">${t('Lernübersicht','Learning overview')}</a></nav>${staff?`<label class="field library-role">${t('Musterrolle','Sample role')}<select id="library-role">${Object.entries(LIBRARY_ROLES).map(([k,v])=>`<option value="${k}" ${LIBRARY.role===k?'selected':''}>${t(...v)}</option>`).join('')}</select></label>`:''}${LIBRARY.error?`<p id="library-error" role="alert" tabindex="-1">${t(...LIBRARY.error)}</p>`:''}${!allowed?`<p class="learning-empty">${t('Dieser Musterrolle sind keine Materialien zugeordnet.','No materials are assigned to this sample role.')}</p>`:staff?`${LIBRARY.role==='teacher'?libraryEditor():''}<section class="learning-panel"><h2>${t('Vorgelegte Fassungen','Submitted versions')}</h2>${LIBRARY.items.length?`<div class="case-list">${LIBRARY.items.map(x=>`<button class="case-card" data-library-select="${x.id}" aria-pressed="${x.id===LIBRARY.selected}"><b>${esc(x.versions.at(-1).data.title)}</b><span>${x.id} · ${libraryStatus(x.versions.at(-1))}</span></button>`).join('')}</div>`:`<p class="learning-empty">${t('Noch kein Material zur Prüfung vorgelegt.','No material submitted for review yet.')}</p>`}</section>${libraryReview()}`:libraryParticipant()}<p class="learning-source">WF-W09-05-01 / WF-W09-05-02 · W9.5 / W11.6. ${t('Teilweise lokale Wege. Produktive Rechte, Curricula, Dateien, Rücknahmen, Benachrichtigungen und Trainerlogik bleiben offen.','Partial local journeys. Production permissions, curricula, files, withdrawals, notifications and trainer logic remain open.')}</p></section>`}
function libraryAction(act,number,target){LIBRARY.error=null;const x=libraryItem(),v=act==='reuse'?x?.versions.find(v=>v.number===Number(number)):libraryVersion();const fail=libraryFail;
 if(!libraryStaff()||LIBRARY.role==='other')return;
 if(act==='preview'&&LIBRARY.role==='teacher'){LIBRARY.preview=true;}
 else if(act==='new'&&LIBRARY.role==='teacher'){LIBRARY.selected=null;LIBRARY.draft={kind:'material',title:'',goal:'',body:'',example:'',exercise:'',translation:''};LIBRARY.note='';LIBRARY.checked=false;}
 else if(act==='submit'&&LIBRARY.role==='teacher'){
  const d=libraryCopy(LIBRARY.draft);for(const k of Object.keys(d))d[k]=d[k].trim();if(!['material','vocabulary'].includes(d.kind)||!d.title||!d.goal||!d.body||d.kind==='vocabulary'&&(!d.example||!d.exercise))return fail('Titel/Begriff, Lernziel und Inhalt sowie beim Wortschatz Beispiel und Übungsbezug ergänzen.','Add title/term, objective and content, plus example and practice prompt for vocabulary.');
  if(v?.status==='pending')return fail('Diese Fassung wartet auf Prüfung. Entscheidung vor einer neuen Vorlage abwarten.','This version awaits review. Wait for a decision before a new submission.');
  if(v&&JSON.stringify(d)===JSON.stringify(v.data))return fail('Unveränderte Fassung nicht erneut vorlegen. Freigegebene Fassung wiederverwenden.','Do not resubmit an unchanged version. Reuse its approved version.');
  const item=x||{id:'DEMO-MAT-'+(LIBRARY.items.length+1),author:'Musterlehrkraft T-01',versions:[],history:[]};if(!x)LIBRARY.items.push(item);const n={number:item.versions.length+1,data:d,status:'pending',reviewer:LIBRARY.missingLead?'head':'lead',reviewNote:'',assignments:[]};item.versions.push(n);LIBRARY.selected=item.id;libraryEvent(item,'Fassung zur Musterprüfung vorgelegt.','Version submitted for sample review.');LIBRARY.note='';LIBRARY.checked=false;
 }else if(['approve','return'].includes(act)){
  if(!v||v.status!=='pending'||LIBRARY.role!==v.reviewer)return fail('Diese Musterrolle ist für diese Fassung nicht prüfzuständig.','This sample role is not the assigned reviewer for this version.');
  if(!LIBRARY.checked||!LIBRARY.note.trim())return fail('Fachliche Prüfnotiz und ausdrückliche Prüfung dieser Fassung erforderlich.','Subject review note and explicit review of this version required.');
  v.status=act==='approve'?'approved':'revision';v.reviewNote=LIBRARY.note.trim();v.reviewedAt=new Date().toISOString();libraryEvent(x,act==='approve'?'Fassung lokal freigegeben.':'Fassung zur Überarbeitung zurückgegeben.',act==='approve'?'Version approved locally.':'Version returned for revision.',v.reviewNote);LIBRARY.checked=false;LIBRARY.note='';
 }else if(['assign','reuse'].includes(act)&&LIBRARY.role==='teacher'){
  const course=act==='reuse'?target:LIBRARY.target;
  if(!v||v.status!=='approved'||!['T-01','T-02'].includes(course))return fail('Nur eine freigegebene Fassung kann einem Musterkurs zugeordnet werden.','Only an approved version can be assigned to a sample course.');
  if(v.assignments.some(a=>a.course===course))return fail('Diese Fassung ist diesem Musterkurs bereits zugeordnet.','This version is already assigned to this sample course.');
  v.assignments.push({course,at:new Date().toISOString()});libraryEvent(x,'Unveränderte Freigabe wiederverwendet.','Unchanged approval reused.',course);
 }else return;render();document.getElementById('library-heading')?.focus();
}
function libraryPractice(key,result){if(libraryStaff()||!['repeat','reviewed'].includes(result))return;const match=LIBRARY.items.flatMap(x=>x.versions.map(v=>({x,v}))).find(({x,v})=>x.id+'-'+v.number===key&&v.status==='approved'&&v.data.kind==='vocabulary'&&v.assignments.some(a=>a.course==='T-01'));if(!match)return;const answer=(LIBRARY.answers[key]||'').trim();if(!answer)return libraryFail('Eigene fiktive Antwort ergänzen.','Add your fictional answer.');(LIBRARY.practice[key]??=[]).push({answer,result,at:new Date().toISOString()});LIBRARY.answers[key]='';LIBRARY.error=null;render();document.getElementById('library-heading')?.focus()}
const libraryBodyBefore=v3Body;v3Body=function(r){return LIBRARY_ROUTES.includes(r)?libraryPage():libraryBodyBefore(r)};
const libraryGuidanceBefore=v3Guidance;v3Guidance=function(a){return LIBRARY_ROUTES.includes(route())?[t('Eine Freigabe gilt für eine Fassung.','Approval belongs to one version.'),t('Entwurf, fachliche Prüfung und zugeordnetes Material bleiben nachvollziehbar getrennt.','Draft, subject review and assigned material remain distinct and traceable.'),[['Bibliothek','Library','/staff/library'],['Meine Materialien','My materials','/portal/drive']]]:libraryGuidanceBefore(a)};
const libraryAssistantBefore=v3Assistant;v3Assistant=function(a){if(!libraryStaff())return libraryAssistantBefore(a);const g=v3Guidance(a);return `<aside class="assistant" id="context-companion" aria-label="${t('Materialbegleitung','Material guidance')}"><div class="assistant-body"><h2>${g[0]}</h2><p>${g[1]}</p>${g[2].map(([de,en,r])=>`<a class="suggestion" href="#${r}">${t(de,en)}${arrow}</a>`).join('')}<p>${t('Keine echten Dateien, Rechteänderungen oder LMS-Freigaben.','No actual files, permission changes or LMS approvals.')}</p></div></aside>`};
const libraryBindBefore=v3Bind;v3Bind=function(){libraryBindBefore();if(!LIBRARY_ROUTES.includes(route()))return;const refresh=()=>{LIBRARY.error=null;render();document.getElementById('library-heading')?.focus()};document.querySelectorAll('[data-library-action]').forEach(e=>e.addEventListener('click',()=>libraryAction(e.dataset.libraryAction,e.dataset.libraryVersion,e.dataset.libraryCourse)));document.getElementById('library-role')?.addEventListener('change',e=>{if(!LIBRARY_ROLES[e.target.value])return;LIBRARY.role=e.target.value;LIBRARY.note='';LIBRARY.checked=false;refresh()});document.querySelectorAll('[data-library-select]').forEach(e=>e.addEventListener('click',()=>{if(LIBRARY.role==='other')return;const x=LIBRARY.items.find(x=>x.id===e.dataset.librarySelect);if(!x)return;LIBRARY.selected=x.id;LIBRARY.draft=libraryCopy(x.versions.at(-1).data);LIBRARY.note='';LIBRARY.checked=false;refresh()}));
 for(const key of Object.keys(LIBRARY.draft))document.getElementById('library-'+key)?.addEventListener(key==='kind'?'change':'input',e=>{if(!libraryStaff()||LIBRARY.role!=='teacher')return;LIBRARY.draft[key]=e.target.value;LIBRARY.preview=false;document.querySelector('.library-preview')?.remove();if(key==='kind')refresh()});
 document.getElementById('library-missing-lead')?.addEventListener('change',e=>{if(LIBRARY.role==='teacher')LIBRARY.missingLead=e.target.checked});document.getElementById('library-target')?.addEventListener('change',e=>{if(['T-01','T-02'].includes(e.target.value))LIBRARY.target=e.target.value});document.getElementById('library-note')?.addEventListener('input',e=>{LIBRARY.note=e.target.value;LIBRARY.checked=false;const c=document.getElementById('library-checked');if(c)c.checked=false});document.getElementById('library-checked')?.addEventListener('change',e=>LIBRARY.checked=e.target.checked);document.querySelectorAll('[data-library-answer]').forEach(e=>e.addEventListener('input',()=>{if(!libraryStaff())LIBRARY.answers[e.dataset.libraryAnswer]=e.value}));document.querySelectorAll('[data-library-practice]').forEach(e=>e.addEventListener('click',()=>libraryPractice(e.dataset.libraryPractice,e.dataset.result)));
};
render();
